// Font proof for the files generated by scripts/fonts/build.py.
//
//   node scripts/fonts/proof.mjs
//
// 1. Writes storage/app/qa/font-proof.html: the generated @font-face rules from
//    resources/scss/base/_fonts.scss inlined (font URLs made relative so they resolve from
//    storage/app/qa/), with approved copy from database/content/*.json in every face and weight.
// 2. Opens it in the installed Google Chrome (file:// fonts need --allow-file-access-from-files).
// 3. Asks Chrome (DevTools CSS.getPlatformFontsForNode) which fonts drew every sample: anything
//    other than a Summit web font means a glyph was missing and a system font filled in.
// 4. Measures each metric-compatible fallback face against its web font (single-line width and
//    wrapped line count at the same measure).
// 5. Writes storage/app/qa/font-proof.png (full page) and storage/app/qa/font-proof.json.
// Exits non-zero when a font fails to load or a sample uses a non-Summit font.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { chromium } from 'playwright-core';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const QA = path.join(ROOT, 'storage', 'app', 'qa');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const fontCss = read('resources/scss/base/_fonts.scss')
  .split('\n').filter((line) => !line.trimStart().startsWith('//')).join('\n')
  .replace(/\n{3,}/g, '\n\n').trim()
  .replaceAll("url('/fonts/", "url('../../../public/fonts/");
const build = JSON.parse(read('storage/app/qa/font-build.json'));
const page01 = JSON.parse(read('database/content/pages.json')).P01;
const ui = JSON.parse(read('database/content/ui_strings.json'));
const PHONE = '+971 52 466 6191';

const LANGS = {
  en: { dir: 'ltr', name: 'English', display: 'Summit Serif', text: 'Summit Sans', displayWeights: [400, 600], textWeights: [400, 500, 600] },
  ru: { dir: 'ltr', name: 'Russian', display: 'Summit Serif', text: 'Summit Sans', displayWeights: [400, 600], textWeights: [400, 500, 600] },
  ar: { dir: 'rtl', name: 'Arabic', display: 'Summit Naskh', text: 'Summit Sans Arabic', displayWeights: [400, 600], textWeights: [400, 500, 600] },
};

function copyFor(loc) {
  const c = page01.content[loc];
  return {
    h1: page01.h1[loc],
    lead: c.hero.lead,
    body: c.hero.body,
    steps: c.review.steps.map((s) => s.title),
    labels: Object.values(c.form_home_variant.labels),
    cta: ui['cta.request_consultation'][loc],
    whatsapp: ui['cta.whatsapp'][loc],
    hours: c.contact.hours,
    brand: ui['brand.name'][loc],
    copyright: ui['footer.copyright'][loc],
  };
}

// The H1 is set on two lines, one sentence per line (spec: hero "The File").
const h1Lines = (h1) => h1.split(/(?<=\.)\s+/).map(esc).join('<br>');

function section(loc) {
  const L = LANGS[loc];
  const c = copyFor(loc);
  const cov = build.coverage[loc];
  // A combining mark is drawn with its base, so isolated harakat sit on a tatweel (U+0640).
  const charset = [...cov.charset].filter((ch) => ch.trim() !== '')
    .map((ch) => (/\p{Mn}/u.test(ch) ? `ـ${ch}` : ch));
  const displayStack = loc === 'ar' ? "'Summit Naskh', 'Summit Serif'" : "'Summit Serif'";
  const textStack = loc === 'ar' ? "'Summit Sans Arabic', 'Summit Sans'" : "'Summit Sans'";
  const displayFb = loc === 'ar' ? "'Summit Arabic Fallback', 'Summit Serif Fallback'" : "'Summit Serif Fallback'";
  const textFb = loc === 'ar' ? "'Summit Arabic Fallback', 'Summit Sans Fallback'" : "'Summit Sans Fallback'";
  const pair = (id, cls, stackWeb, stackFb, weight, html) => `
    <div class="pair" data-pair="${loc} ${id}">
      <div class="web ${cls}" style="font-family:${stackWeb};font-weight:${weight}">${html}</div>
      <div class="fb ${cls}" style="font-family:${stackFb};font-weight:${weight}" data-fallback="${loc} ${id}">${html}</div>
      <p class="readout" dir="ltr" lang="en"></p>
    </div>`;
  return `
  <section class="lang" lang="${loc}" dir="${L.dir}">
    <p class="tag" dir="ltr" lang="en">${loc.toUpperCase()} · ${L.name} · display ${esc(displayStack)} · text ${esc(textStack)}</p>
    ${L.displayWeights.map((w) => `
    <p class="label" dir="ltr" lang="en">Display ${w}</p>
    <h1 class="display" style="font-family:${displayStack};font-weight:${w}" data-check="${loc} display ${w}">${h1Lines(c.h1)}</h1>`).join('')}
    <div class="cols">
      <div>
        <p class="label" dir="ltr" lang="en">Text 400 (lead, body)</p>
        <p class="lead" style="font-family:${textStack};font-weight:400" data-check="${loc} text 400 lead">${esc(c.lead)}</p>
        <p class="body" style="font-family:${textStack};font-weight:400" data-check="${loc} text 400 body">${esc(c.body)}</p>
        <p class="label" dir="ltr" lang="en">Text 500 (form labels)</p>
        <p class="ui" style="font-family:${textStack};font-weight:500" data-check="${loc} text 500">${c.labels.map(esc).join('<br>')}</p>
        <p class="label" dir="ltr" lang="en">Text 600 (calls to action)</p>
        <p class="cta" style="font-family:${textStack};font-weight:600" data-check="${loc} text 600">${esc(c.cta)}<br>${esc(c.whatsapp)}</p>
        <p class="label" dir="ltr" lang="en">Phone (LTR, tabular figures) and hours</p>
        <p class="body" style="font-family:${textStack}"><bdi dir="ltr" data-check="${loc} phone">${PHONE}</bdi></p>
        <p class="body" style="font-family:${textStack}" data-check="${loc} hours">${esc(c.hours)}</p>
      </div>
      <div>
        <p class="label" dir="ltr" lang="en">Display 400 (method steps)</p>
        <p class="steps" style="font-family:${displayStack};font-weight:400" data-check="${loc} steps">${c.steps.map(esc).join('<br>')}</p>
        <p class="label" dir="ltr" lang="en">Brand name: display 600, text 400 (footer copyright)</p>
        <p class="steps" style="font-family:${displayStack};font-weight:600" data-check="${loc} brand display">${esc(c.brand)}</p>
        <p class="body" style="font-family:${textStack};font-weight:400" data-check="${loc} brand text">${esc(c.copyright)}</p>
        <p class="label" dir="ltr" lang="en">All ${cov.distinct} distinct characters of the approved ${loc.toUpperCase()} copy (${cov.files} DOCX files): display, then text</p>
        <p class="charset" style="font-family:${displayStack}" data-check="${loc} charset display">${charset.map(esc).join(' ')}</p>
        <p class="charset" style="font-family:${textStack}" data-check="${loc} charset text">${charset.map(esc).join(' ')}</p>
      </div>
    </div>
    <p class="label" dir="ltr" lang="en">Fallback faces: web font (ink) above, metric-compatible fallback (grey) below, same measure</p>
    ${pair('display 400', 'display', displayStack, displayFb, 400, h1Lines(c.h1))}
    <div class="cols">
      <div>${pair('text 400 lead', 'lead measure', textStack, textFb, 400, esc(c.lead))}</div>
      <div>${pair('text 400 body', 'body measure', textStack, textFb, 400, esc(c.body))}</div>
    </div>
    <div class="cols">
      <div>${pair('display 600', 'steps', displayStack, displayFb, 600, c.steps.map(esc).join('<br>'))}</div>
      <div>${pair('text 500', 'ui', textStack, textFb, 500, c.labels.slice(0, 4).map(esc).join('<br>'))}</div>
    </div>
    ${pair('text 600', 'cta', textStack, textFb, 600, esc(c.cta))}
  </section>`;
}

const files = build.files.map((f) => `${f.name} ${(f.bytes / 1024).toFixed(1)} KB`).join(' · ');
const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Summit font proof</title>
<style>
/* Generated @font-face rules from resources/scss/base/_fonts.scss (font URLs relative to storage/app/qa/) */
${fontCss}

/* Proof sheet layout (QA only) */
:root { --ink: #111; --muted: #6b6b6b; --rule: #e4e4e1; --fb: #8c8c88; }
* { box-sizing: border-box; }
body { margin: 0; padding: 2rem 2.5rem 3rem; background: #fff; color: var(--ink); font: 400 0.8125rem/1.45 'Summit Sans', sans-serif; }
.meta { margin: 0 0 0.25rem; color: var(--muted); }
.lang { border-top: 2px solid var(--ink); margin-top: 2rem; padding-top: 0.75rem; }
.tag { font: 600 0.8125rem/1.3 'Summit Sans', sans-serif; margin: 0 0 0.5rem; }
.label { font: 500 0.6875rem/1.3 'Summit Sans', sans-serif; color: var(--muted); margin: 1rem 0 0.25rem; letter-spacing: 0.02em; }
h1, .display { font-size: 4.5rem; line-height: 1.05; margin: 0; font-weight: 400; }
[lang="ru"] .display, [lang="ru"] h1 { font-size: 4rem; }
[lang="ar"] .display, [lang="ar"] h1 { font-size: 4rem; line-height: 1.35; }
.lead { font-size: 1.25rem; line-height: 1.55; margin: 0 0 0.5rem; }
.body { font-size: 1.125rem; line-height: 1.6; margin: 0 0 0.5rem; }
[lang="ar"] .lead { line-height: 1.75; } [lang="ar"] .body { line-height: 1.8; }
.ui { font-size: 0.875rem; line-height: 1.5; margin: 0; }
.cta { font-size: 1rem; line-height: 1.5; margin: 0; }
.steps { font-size: 1.5rem; line-height: 1.25; margin: 0; }
[lang="ar"] .steps { line-height: 1.5; }
.charset { font-size: 1.375rem; line-height: 1.6; margin: 0 0 0.5rem; word-break: break-all; }
.cols { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; }
.measure { max-width: 34rem; }
.pair { margin: 0.75rem 0 0; padding-top: 0.5rem; border-top: 1px solid var(--rule); }
.pair .fb { color: var(--fb); }
.readout { font: 400 0.6875rem/1.3 'Summit Sans', sans-serif; color: var(--muted); margin: 0.25rem 0 0; }
.readout.bad { color: #b42318; }
.results { margin-top: 2rem; border-top: 2px solid var(--ink); padding-top: 0.75rem; }
.results table { border-collapse: collapse; width: 100%; font-size: 0.75rem; }
.results td, .results th { border-bottom: 1px solid var(--rule); padding: 0.2rem 0.5rem 0.2rem 0; text-align: start; vertical-align: top; }
.results .bad { color: #b42318; font-weight: 600; }
</style>
</head>
<body>
<p class="meta">Summit Legal Consultancy · web font proof · generated by scripts/fonts/proof.mjs from the files built by scripts/fonts/build.py (google/fonts@${build.google_fonts_commit.slice(0, 12)})</p>
<p class="meta">${esc(files)}</p>
${Object.keys(LANGS).map(section).join('\n')}
<div class="results" id="results"></div>
<script>
(async () => {
  const faces = [...document.fonts];
  await Promise.allSettled(faces.map((f) => f.load()));
  await document.fonts.ready;
  const out = { faces: faces.map((f) => ({ family: f.family.replace(/["']/g, ''), weight: f.weight, status: f.status, unicodeRange: f.unicodeRange })), pairs: [] };
  const measure = (el) => {
    const clone = el.cloneNode(true);
    clone.style.position = 'absolute';
    clone.style.whiteSpace = 'nowrap';
    clone.style.width = 'auto';
    clone.style.maxWidth = 'none';
    clone.style.visibility = 'hidden';
    el.parentNode.appendChild(clone);
    const width = clone.getBoundingClientRect().width;
    clone.remove();
    return width;
  };
  for (const pair of document.querySelectorAll('[data-pair]')) {
    const web = pair.querySelector('.web');
    const fb = pair.querySelector('.fb');
    const lh = parseFloat(getComputedStyle(web).lineHeight);
    const r = {
      id: pair.dataset.pair,
      webWidth: measure(web), fallbackWidth: measure(fb),
      webLines: Math.round(web.getBoundingClientRect().height / lh),
      fallbackLines: Math.round(fb.getBoundingClientRect().height / lh),
      webHeight: web.getBoundingClientRect().height, fallbackHeight: fb.getBoundingClientRect().height,
    };
    r.widthDelta = r.fallbackWidth / r.webWidth - 1;
    out.pairs.push(r);
    const readout = pair.querySelector('.readout');
    readout.textContent = 'single-line width: web ' + r.webWidth.toFixed(1) + ' · fallback ' + r.fallbackWidth.toFixed(1)
      + ' (' + (r.widthDelta >= 0 ? '+' : '') + (r.widthDelta * 100).toFixed(2) + '%) · wrapped lines: web ' + r.webLines + ' · fallback ' + r.fallbackLines
      + ' · block height: web ' + r.webHeight.toFixed(1) + ' · fallback ' + r.fallbackHeight.toFixed(1);
    if (r.webLines !== r.fallbackLines || Math.abs(r.widthDelta) > 0.03) readout.classList.add('bad');
  }
  window.__proof = out;
  document.documentElement.dataset.done = '1';
})();
</script>
</body>
</html>
`;

fs.mkdirSync(QA, { recursive: true });
const htmlPath = path.join(QA, 'font-proof.html');
fs.writeFileSync(htmlPath, html);

const browser = await chromium.launch({ channel: 'chrome', args: ['--allow-file-access-from-files'] });
let failed = false;
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 1 });
  const consoleErrors = [];
  page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  page.on('requestfailed', (r) => consoleErrors.push(`request failed: ${r.url()} ${r.failure()?.errorText}`));
  await page.goto(pathToFileURL(htmlPath).href);
  await page.waitForFunction(() => document.documentElement.dataset.done === '1', null, { timeout: 30000 });
  const proof = await page.evaluate(() => window.__proof);

  // Which fonts did Chrome actually use for every checked sample?
  const cdp = await page.context().newCDPSession(page);
  await cdp.send('DOM.enable');
  await cdp.send('CSS.enable');
  const { root } = await cdp.send('DOM.getDocument', { depth: -1 });
  // Web samples must be drawn only by Summit web fonts (renamed internally to Summit*); fallback
  // samples only by local system fonts.
  const checks = [];
  for (const [selector, fallback] of [['[data-check]', false], ['[data-fallback]', true]]) {
    const { nodeIds } = await cdp.send('DOM.querySelectorAll', { nodeId: root.nodeId, selector });
    for (const nodeId of nodeIds) {
      const { attributes } = await cdp.send('DOM.getAttributes', { nodeId });
      const label = attributes[attributes.indexOf(fallback ? 'data-fallback' : 'data-check') + 1];
      const { fonts } = await cdp.send('CSS.getPlatformFontsForNode', { nodeId });
      const summit = (f) => /^Summit/.test(f.postScriptName || f.familyName);
      const ok = fonts.length > 0 && (fallback ? fonts.every((f) => !summit(f)) : fonts.every(summit));
      checks.push({ label, fallback, ok, fonts: fonts.map((f) => ({ family: f.familyName, postScriptName: f.postScriptName, custom: f.isCustomFont, glyphs: f.glyphCount })) });
    }
  }

  const faceErrors = proof.faces.filter((f) => f.status !== 'loaded');
  const badChecks = checks.filter((c) => !c.ok);
  failed = faceErrors.length > 0 || badChecks.length > 0 || consoleErrors.length > 0;

  // Put the results on the sheet before the screenshot (DOM nodes + textContent only).
  await page.evaluate(({ checks, proof, faceErrors, consoleErrors }) => {
    const el = document.getElementById('results');
    const add = (parent, tag, text, cls) => {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      if (cls) node.className = cls;
      parent.appendChild(node);
      return node;
    };
    const fmt = (fonts) => fonts.map((f) => f.postScriptName + ' × ' + f.glyphs).join(', ');
    const table = (title, rows) => {
      add(el, 'p', title, 'tag');
      const t = add(el, 'table');
      for (const cells of rows) {
        const tr = add(t, 'tr', undefined, cells.bad ? 'bad' : '');
        for (const cell of cells.values) add(tr, 'td', cell);
      }
    };
    const web = checks.filter((c) => !c.fallback);
    const fb = checks.filter((c) => c.fallback);
    table(`Chrome DevTools: fonts that drew each sample (${web.length} samples; a non-Summit font would mean a missing glyph)`,
      web.map((c) => ({ bad: !c.ok, values: [c.ok ? 'ok' : 'MISSING GLYPHS', c.label, fmt(c.fonts)] })));
    table(`Local fonts that drew the ${fb.length} fallback samples`,
      fb.map((c) => ({ bad: !c.ok, values: [c.ok ? 'ok' : 'NOT A LOCAL FONT', c.label, fmt(c.fonts)] })));
    add(el, 'p', `Font faces: ${proof.faces.length} declared, ${proof.faces.filter((f) => f.status === 'loaded').length} loaded`
      + (faceErrors.length ? `, errors: ${faceErrors.map((f) => `${f.family} ${f.weight} ${f.status}`).join('; ')}` : '')
      + (consoleErrors.length ? ` · console: ${consoleErrors.join(' | ')}` : ' · console clean'), 'tag');
  }, { checks, proof, faceErrors, consoleErrors });

  const pngPath = path.join(QA, 'font-proof.png');
  await page.screenshot({ path: pngPath, fullPage: true });
  fs.writeFileSync(path.join(QA, 'font-proof.json'), JSON.stringify({ chrome: browser.version(), faces: proof.faces, pairs: proof.pairs, checks, consoleErrors }, null, 2) + '\n');

  console.log(`Chrome ${browser.version()}: ${proof.faces.length} faces, ${proof.faces.length - faceErrors.length} loaded`);
  for (const c of checks) {
    console.log(`${c.ok ? 'ok  ' : 'FAIL'} ${c.label.padEnd(30).slice(0, 60)} ${c.fonts.map((f) => `${f.postScriptName}${f.custom ? '' : ' (system)'}×${f.glyphs}`).join(', ')}`);
  }
  console.log('fallback pairs (single-line width delta, wrapped lines web/fallback):');
  for (const p of proof.pairs) {
    console.log(`  ${p.id.padEnd(18)} ${(p.widthDelta * 100).toFixed(2).padStart(6)}%  lines ${p.webLines}/${p.fallbackLines}  height ${p.webHeight.toFixed(1)}/${p.fallbackHeight.toFixed(1)}`);
  }
  if (consoleErrors.length) console.log('console:', consoleErrors);
  console.log(`wrote ${path.relative(ROOT, htmlPath)}, ${path.relative(ROOT, pngPath)}, storage/app/qa/font-proof.json`);
} finally {
  await browser.close();
}
process.exit(failed ? 1 : 0);
